mapper.select:
SELECT r.id AS review_id,r.user_id AS reviewer_user_id,ru.full_name AS reviewer_name, r.place_id,h.id AS hotel_id,r.activity_booking_id,COALESCE(p.title,a.title) AS subject_name, r.overall_rating,r.text AS review_text,r.photos,r.created_at AS review_created_at, rr.id AS response_id,COALESCE(rr.organization_id,h.organization_id,a.host_organization_id) AS organization_id,rr.responder_user_id,res.full_name AS responder_name, rr.response_text,rr.status AS response_status,rr.data_version AS response_version, rr.created_at AS response_created_at,rr.updated_at AS response_updated_at FROM user_reviews r JOIN users ru ON ru.id=r.user_id LEFT JOIN hotel_profiles h ON h.place_id=r.place_id LEFT JOIN places p ON p.id=r.place_id LEFT JOIN activity_bookings a ON a.id=r.activity_booking_id LEFT JOIN marketplace_review_responses rr ON rr.review_id=r.id LEFT JOIN users res ON res.id=rr.responder_user_id
WHERE (p.title ILIKE CONCAT('%',#{query},'%') OR a.title ILIKE CONCAT('%',#{query},'%') OR r.text ILIKE CONCAT('%',#{query},'%'))
ORDER BY r.created_at DESC LIMIT #{limit} OFFSET #{offset}
